"""Fertige Antworten pro Ansicht ("View-Models") für das PM-Cockpit (Owner: Lead).

Warum: Das Frontend soll nur anzeigen, nie rechnen. Jede Zahl, jedes Label und jeder Satz
entsteht hier in Python, damit Frontend, CSV und Pitch dieselben Werte zeigen und alles
ohne Browser testbar ist (tests/test_views.py). Reine Funktionen: lesen den Zustand, ändern nichts.
"""

from __future__ import annotations

from collections import Counter

from core.model_parts import DataCoverage, coverage_badge
from core.models import Requirement, Signal, SourceType
from requirements_engine import scoring

LEVEL_LABEL = {"A": "stark belegt", "B": "mittel belegt", "C": "schwach belegt", "D": "Annahme"}
FACTOR_LABEL = {
    "customer_pain": "Kundenschmerz", "reach": "Reichweite (Kunden × Volumen)",
    "satisfaction_gap": "Zufriedenheitslücke (Studie)", "competitive_pressure": "Wettbewerbsdruck",
    "future_relevance": "Zukunftsrelevanz", "effort_inverse": "Geringer Aufwand",
}
TRUST_ORDER = {"high": 0, "medium": 1, "low": 2}
ENGINE_LABEL = {"BEVE": "BEV"}  # BMW schreibt "BEVE"; im UI heißt es überall BEV


def coverage(state) -> DataCoverage:
    """Abdeckung aus dem Bundle; ältere Bundles ohne Feld: aus den Belegen zählen."""
    cov = state.scenario.data_coverage
    if any(v for k, v in cov.model_dump().items() if k != "badge"):
        return cov.model_copy(update={"badge": coverage_badge(cov.feedback)})
    counts = Counter(e.source_type for e in state.evidence.values())
    feedback = state.funnel.get("evidence", 0) - sum(c for t, c in counts.items() if t != SourceType.FEEDBACK)
    feedback = max(feedback, 0) if counts.get(SourceType.FEEDBACK) else 0
    return DataCoverage(
        feedback=feedback, study=counts.get(SourceType.STUDY, 0), sales=counts.get(SourceType.SALES, 0),
        options=counts.get(SourceType.OPTION_LIST, 0), web=counts.get(SourceType.WEB, 0),
        external=counts.get(SourceType.EXTERNAL_STAT, 0) + counts.get(SourceType.FEEDBACK_EXTERNAL, 0),
        badge=coverage_badge(feedback),
    )


def _ranked(state) -> list[Requirement]:
    return sorted(state.requirements.values(), key=lambda r: r.rank)


def scenario_card(state) -> dict:
    """Eine Kachel im Szenario-Wähler."""
    ranked = _ranked(state)
    cov = coverage(state)
    return {
        **state.scenario.model_dump(mode="json"), "data_coverage": cov.model_dump(), "badge": cov.badge,
        "headline_numbers": {
            "evidence": state.funnel.get("evidence", 0), "signals": len(state.signals),
            "requirements": len(ranked), "top_title": ranked[0].title if ranked else None,
        },
    }


def warnings(state) -> list[str]:
    """Config-Warnungen + Regeln, die der PM sehen muss, bevor er der Liste vertraut."""
    out = list(state.scenario.warnings)
    unmapped = state.context.get("unmapped_topics") or {}
    if unmapped:
        out.append(f"{len(unmapped)} Themen ohne Kategorie ({sum(unmapped.values())} Kommentare), "
                   "nicht in der Priorisierung.")
    without = [r.id for r in state.requirements.values() if r.evidence_level.value == "D" and not r.assumptions]
    if without:
        out.append(f"{len(without)} Annahme-Anforderungen ohne ausgeschriebene Annahme: {', '.join(without)}")
    return out


def overview(state) -> dict:
    """Startseite: Trichter, Top 3, Stufen-Verteilung, Warnungen, Quellen-Mix."""
    ranked = _ranked(state)
    levels = Counter(r.evidence_level.value for r in ranked)
    approved = sum(r.status.value == "approved" for r in ranked)
    return {
        "scenario_id": state.scenario.id,
        "funnel": {**state.funnel, "signals": len(state.signals), "requirements": len(ranked), "approved": approved},
        "top3": [{"id": r.id, "title": r.title, "score": r.score, "rank": r.rank, "evidence_level": r.evidence_level,
                  "level_label": LEVEL_LABEL[r.evidence_level.value], "badges": r.badges} for r in ranked[:3]],
        "level_distribution": {lvl: levels.get(lvl, 0) for lvl in "ABCD"},
        "warnings": warnings(state),
        "source_mix": coverage(state).model_dump(),
        "generated_at": state.funnel.get("generated_at"),
    }


def _linked(state, req: Requirement) -> list[Signal]:
    return [state.signals[s] for s in req.signal_ids if s in state.signals]


def waterfall(req: Requirement) -> list[dict]:
    """Score-Wasserfall: Beitrag je Faktor (größter zuerst), am Ende der Abschlag der Evidenzstufe."""
    steps = [{"factor": k, "label": FACTOR_LABEL.get(k, k), "value": f.value, "weight": f.weight,
              "contribution": f.contribution, "sentence": f.explanation}
             for k, f in sorted(req.score_breakdown.items(), key=lambda kv: -kv[1].contribution)]
    raw = round(sum(s["contribution"] for s in steps), 1)
    confidence = scoring.CONFIDENCE[req.evidence_level]
    steps.append({"factor": "confidence", "label": f"Evidenzstufe {req.evidence_level.value}", "value": confidence,
                  "weight": None, "contribution": round(req.score - raw, 1),
                  "sentence": f"{LEVEL_LABEL[req.evidence_level.value]}: Rohwert {raw} × {confidence} = {req.score}"})
    return steps


def segments(linked: list[Signal]) -> dict[str, dict[str, int]]:
    """Segment-Zählung aller verknüpften Befunde zusammengezählt (für die Balken)."""
    out: dict[str, Counter] = {}
    for sig in linked:
        for dim, counts in sig.segments.items():
            for seg, n in counts.items():
                out.setdefault(dim, Counter())[ENGINE_LABEL.get(seg, seg)] += n
    return {dim: dict(c.most_common()) for dim, c in out.items()}


def _quote(ev) -> dict:
    m = ev.meta
    return {"id": ev.id, "text": ev.text, "source_name": ev.source_name, "polarity": ev.polarity,
            "country": m.get("country"), "engine": ENGINE_LABEL.get(m.get("engine", ""), m.get("engine")),
            "source_letter": m.get("source_letter"), "feedback_type": m.get("feedback_type")}


def robustness_sentence(req: Requirement) -> str | None:
    rob = req.robustness
    if rob is None:
        return None
    span = f"Rang {rob.rank_min}" if rob.rank_min == rob.rank_max else f"Rang {rob.rank_min}–{rob.rank_max}"
    return f"In {round(rob.top3_share * 100)} % von {rob.runs} zufälligen Gewichtungen (±30 %) in den Top 3 ({span})."


def explain(state, req: Requirement, history: list) -> dict:
    """Detailseite: alles, was der PM zum Prüfen einer Anforderung braucht."""
    linked = _linked(state, req)
    ev_ids = sorted({e for s in linked for e in s.evidence_ids})
    evidence = [state.evidence[e] for e in ev_ids if e in state.evidence]
    feedback = [e for e in evidence if e.source_type in (SourceType.FEEDBACK, SourceType.FEEDBACK_EXTERNAL)]
    web = [e for e in evidence if e.source_type in (SourceType.WEB, SourceType.EXTERNAL_STAT)]
    by_id = {s.id: s for s in linked}
    signal_conflicts = sorted({tuple(sorted((s.id, o))) for s in linked for o in s.conflicts_with if o in by_id})
    return {
        "requirement": req, "level_label": LEVEL_LABEL[req.evidence_level.value],
        "waterfall": waterfall(req),
        "quotes": [_quote(e) for e in sorted(feedback, key=lambda e: e.polarity)[:5]],
        "segments": segments(linked),
        "conflicts": [c.model_dump() for c in req.segment_conflicts]
        + [{"dimension": "signal", "statement": f'"{by_id[a].title}" widerspricht "{by_id[b].title}"',
            "signal_ids": [a, b]} for a, b in signal_conflicts],
        "assumptions": req.assumptions, "uncertainties": req.uncertainties, "horizon": req.horizon,
        "offer_check": req.offer_check,
        "web_sources": sorted(({"id": e.id, "publisher": e.meta.get("publisher", e.source_name), "url": e.url,
                                "text": e.text, "trust": e.meta.get("trust", "medium")} for e in web),
                              key=lambda w: TRUST_ORDER.get(w["trust"], 3)),
        "study": [s.study_link.model_dump() for s in linked if s.study_link],
        "robustness": req.robustness, "robustness_sentence": robustness_sentence(req),
        "business": req.business,
        "signals": linked, "evidence": evidence, "history": history,
    }


def whatif(state, weights: dict[str, float]) -> list[dict]:
    """Neue Reihenfolge für Probe-Gewichte, OHNE zu speichern (kein Audit, Store unverändert)."""
    w = scoring.normalize_weights(weights)
    scored = []
    for req in state.requirements.values():
        values = {k: f.value for k, f in req.score_breakdown.items()}
        values["effort_inverse"] = scoring.effort_factor(req.effort)
        new_score, _ = scoring.score(values, {}, req.evidence_level, w)
        scored.append((req, new_score))
    scored.sort(key=lambda rs: -rs[1])
    return [{"id": r.id, "title": r.title, "evidence_level": r.evidence_level, "old_rank": r.rank, "new_rank": i,
             "rank_change": r.rank - i, "old_score": r.score, "new_score": s}
            for i, (r, s) in enumerate(scored, start=1)]

"""Vergleich über Szenarien: Portfolio-Matrix und Markt-Vergleich (Owner: Lead).

Warum: BMW will "scale across vehicle lines and markets". Die Matrix zeigt, ob ein Thema
eine Plattform-Entscheidung ist (überall oben) oder nur ein Modell bzw. einen Markt betrifft.
Die Klassen sind Regeln in Python, damit der PM sie nachrechnen kann.
"""

from __future__ import annotations

from core.models import Category, Requirement
from core.views import LEVEL_LABEL, coverage

TOP_N = 5  # "oben" heißt: mindestens eine Anforderung des Themas unter den ersten 5


def _best_per_category(requirements) -> dict[str, Requirement]:
    best: dict[str, Requirement] = {}
    for req in sorted(requirements, key=lambda r: r.rank):
        best.setdefault(req.category.value, req)
    return best


def _cell(req: Requirement | None) -> dict | None:
    if req is None:
        return None
    return {"requirement_id": req.id, "title": req.title, "rank": req.rank, "score": req.score,
            "evidence_level": req.evidence_level, "level_label": LEVEL_LABEL[req.evidence_level.value]}


def classify(top_scenarios: list, all_scenarios: list) -> str:
    """Regel: in ≥ 2/3 aller Szenarien oben = plattformweit; nur ein Modell = modellspezifisch;
    nur ein Markt = marktspezifisch; sonst gemischt. Keine Nennung oben = nicht oben."""
    if not top_scenarios:
        return "nicht oben"
    if len(top_scenarios) >= max(2, round(len(all_scenarios) * 2 / 3)):
        return "plattformweit"
    if len(top_scenarios) == 1:
        return "einzeln"
    if len({s.derivative for s in top_scenarios}) == 1:
        return "modellspezifisch"
    if len({s.market for s in top_scenarios}) == 1:
        return "marktspezifisch"
    return "gemischt"


def portfolio(states: dict) -> dict:
    """Matrix Kategorie × Szenario mit bestem Rang und Evidenzstufe je Zelle."""
    scenario_ids = sorted(states)
    best = {sid: _best_per_category(states[sid].requirements.values()) for sid in scenario_ids}
    scenarios = [states[sid].scenario for sid in scenario_ids]
    rows = []
    for cat in Category:
        cells = {sid: _cell(best[sid].get(cat.value)) for sid in scenario_ids}
        top = [states[sid].scenario for sid in scenario_ids if cells[sid] and cells[sid]["rank"] <= TOP_N]
        rows.append({"category": cat.value, "cells": cells, "class": classify(top, scenarios),
                     "top_in": [s.id for s in top]})
    rows.sort(key=lambda r: (-len(r["top_in"]), r["category"]))
    return {
        "scenarios": [{"id": s.id, "model_name": s.model_name, "market": s.market,
                       "data_coverage": coverage(states[s.id]).model_dump()} for s in scenarios],
        "rows": rows, "top_n": TOP_N,
        "rule": "plattformweit = in mind. 2/3 der Szenarien unter den Top 5; modell-/marktspezifisch = nur ein "
                "Modell bzw. ein Markt; einzeln = nur ein Szenario.",
    }


def compare(state_a, state_b) -> dict:
    """Gleiche Themen nebeneinander: Rang und Unzufriedenheit (Studie) in Szenario A und B."""
    best_a = _best_per_category(state_a.requirements.values())
    best_b = _best_per_category(state_b.requirements.values())
    opp_a = {o.get("category"): o.get("dissatisfaction") for o in state_a.opportunities}
    opp_b = {o.get("category"): o.get("dissatisfaction") for o in state_b.opportunities}
    rows = []
    for cat in Category:
        a, b = best_a.get(cat.value), best_b.get(cat.value)
        if not a and not b:
            continue
        rank_diff = (a.rank - b.rank) if a and b else None
        rows.append({"category": cat.value, "a": _cell(a), "b": _cell(b), "rank_diff": rank_diff,
                     "dissatisfaction_a": opp_a.get(cat.value), "dissatisfaction_b": opp_b.get(cat.value),
                     "sentence": _compare_sentence(cat.value, a, b, state_a.scenario.id, state_b.scenario.id)})
    rows.sort(key=lambda r: min(x["rank"] for x in (r["a"], r["b"]) if x))
    return {"a": state_a.scenario.id, "b": state_b.scenario.id, "rows": rows}


def _compare_sentence(category: str, a, b, id_a: str, id_b: str) -> str:
    if a and not b:
        return f"{category}: nur in {id_a} eine Anforderung (Rang {a.rank})."
    if b and not a:
        return f"{category}: nur in {id_b} eine Anforderung (Rang {b.rank})."
    if a.rank == b.rank:
        return f"{category}: in beiden Märkten Rang {a.rank}."
    higher, lower = (id_a, id_b) if a.rank < b.rank else (id_b, id_a)
    return f"{category}: in {higher} wichtiger (Rang {min(a.rank, b.rank)} vs. {max(a.rank, b.rank)} in {lower})."

"""Ehrlichkeits- und Zukunfts-Ansichten: Lücken, Trends, Chancen-Karte, Beleg-Browser (Owner: Lead).

Warum: BMW fragt nach "understanding of uncertainty" und "3-5 years ahead". Diese Ansichten
zeigen, wo wir raten (Stufe C/D, fehlende Quellen) und welche Studie BMW als Nächstes
fahren sollte. Alles regelbasiert, kein LLM.
"""

from __future__ import annotations

from core.models import SignalKind, SourceType
from core.views import LEVEL_LABEL, coverage

# Welche Studie schließt die Lücke? Feste Vorschläge je Kategorie, damit es nachvollziehbar bleibt.
NEXT_STUDY = {
    "exterior": "Design-Klinik mit Bildvarianten",
    "interior": "Sitzprobe / Interieur-Klinik",
    "comfort_space": "Raum- und Alltags-Test mit Bestandskunden",
    "infotainment_digital": "Bedien-Usability-Test (Blindbedienung, Aufgabenzeit)",
    "driving_experience": "Probefahrt-Befragung nach Antriebsart",
    "range_charging": "Lade-Tagebuch-Studie mit BEV-Fahrern",
    "driver_assistance": "Assistenz-Akzeptanz-Befragung",
    "quality_perception": "Haptik- und Qualitäts-Klinik",
    "variants_packages": "Conjoint-Analyse zu Paketen und Preisen",
}
COVERAGE_GAP = {
    "feedback": "Keine Kundenkommentare für diesen Markt: Befunde stützen sich nur auf Studie, Absatz und Web.",
    "study": "Keine Kundenstudie: Zufriedenheitslücken sind nicht messbar.",
    "sales": "Keine Absatzzahlen: Reichweite ist geschätzt.",
    "options": "Keine Optionsliste: wir wissen nicht, was es heute schon gibt.",
    "web": "Keine Webbelege: Wettbewerb und Trends fehlen.",
}
QUADRANTS = ("Chance", "Stärke halten", "Beobachten", "Nebensache")
IMPORTANT_FROM = 0.5      # Wichtigkeit ≥ 0,5 = wichtig
DISSATISFIED_FROM = 0.08  # ≥ 8 % Unzufriedene = Problem (US-Studie: Anteil der drei schlechtesten Stufen)


def gaps(state) -> dict:
    """Was wir nicht wissen: schwach belegte Anforderungen, fehlende Quellen, nächste Studie."""
    cov = coverage(state).model_dump()
    weak = [r for r in sorted(state.requirements.values(), key=lambda r: r.rank)
            if r.evidence_level.value in ("C", "D")]
    return {
        "scenario_id": state.scenario.id,
        "weak_requirements": [{
            "id": r.id, "title": r.title, "rank": r.rank, "evidence_level": r.evidence_level,
            "level_label": LEVEL_LABEL[r.evidence_level.value], "assumptions": r.assumptions,
            "why": (r.uncertainties or r.assumptions or [LEVEL_LABEL[r.evidence_level.value]])[0],
            "next_study": NEXT_STUDY.get(r.category.value, "Gezielte Kundenbefragung"),
        } for r in weak],
        "missing_sources": [text for key, text in COVERAGE_GAP.items() if not cov.get(key)],
        "share_weak": round(len(weak) / len(state.requirements), 2) if state.requirements else 0.0,
    }


def trends(state) -> dict:
    """Trendradar: Trend-Befunde und Zukunftswetten mit Horizont heute / Nachfolger."""
    horizon = state.scenario.successor_horizon
    items = []
    for sig in state.signals.values():
        if sig.kind == SignalKind.TREND:
            items.append({"topic": sig.title, "category": sig.category, "horizon": horizon, "kind": "trend",
                          "strength": sig.mention_count, "sources": sig.source_types, "signal_id": sig.id,
                          "evidence_level": None})
    for req in state.requirements.values():
        if req.horizon == "next_gen":
            items.append({"topic": req.title, "category": req.category, "horizon": horizon, "kind": "bet",
                          "strength": req.score, "sources": sorted({t for s in req.signal_ids if s in state.signals
                                                                    for t in state.signals[s].source_types}),
                          "requirement_id": req.id, "evidence_level": req.evidence_level,
                          "assumptions": req.assumptions})
    items.sort(key=lambda i: -i["strength"])
    return {"scenario_id": state.scenario.id, "successor_horizon": horizon, "rings": ["heute", horizon],
            "items": items}


def quadrant(importance: float, dissatisfaction: float) -> str:
    """Importance-Performance-Analyse: wichtig + unzufrieden = Chance."""
    important = importance >= IMPORTANT_FROM
    unhappy = dissatisfaction >= DISSATISFIED_FROM
    if important:
        return "Chance" if unhappy else "Stärke halten"
    return "Beobachten" if unhappy else "Nebensache"


def opportunities(state) -> dict:
    """Chancen-Karte aus der Studie. Quadrant wird hier neu gerechnet, damit die Regel an einer Stelle lebt."""
    points = [{**o, "quadrant": quadrant(o["importance"], o["dissatisfaction"])}
              for o in state.opportunities if o.get("importance") is not None and o.get("dissatisfaction") is not None]
    return {"scenario_id": state.scenario.id, "points": points, "quadrants": list(QUADRANTS),
            "thresholds": {"importance": IMPORTANT_FROM, "dissatisfaction": DISSATISFIED_FROM}}


def evidence_page(state, signal: str | None = None, segment: str | None = None, q: str | None = None,
                  page: int = 1, size: int = 20) -> dict:
    """Beleg-Browser: gefiltert und seitenweise. segment z. B. "engine:BEV" oder "country:KR"."""
    items = list(state.evidence.values())
    if signal:
        ids = set(state.signals[signal].evidence_ids) if signal in state.signals else set()
        items = [e for e in items if e.id in ids]
    if segment and ":" in segment:
        key, value = segment.split(":", 1)
        meta_key = {"source": "source_letter"}.get(key, key)
        values = {value, "BEVE"} if value == "BEV" else {value}
        items = [e for e in items if e.meta.get(meta_key) in values]
    if q:
        items = [e for e in items if q.lower() in e.text.lower()]
    items.sort(key=lambda e: (e.source_type != SourceType.FEEDBACK, e.id))
    page = max(page, 1)
    return {"total": len(items), "page": page, "size": size,
            "items": [e.model_dump(mode="json") for e in items[(page - 1) * size: page * size]]}

